    html+='<section class="os-card os-accent os-next-step"><div class="os-square-icon">'+icon('users')+'</div><div><p class="os-overline">Próximo passo para o piloto automático</p><h3>Traga seus clientes para o Orion</h3><p>Com a sua base cadastrada, fica mais fácil acompanhar os atendimentos e cuidar de cada retorno.</p>'+routeButton('Cadastrar clientes','clientes','os-small','arrow')+'</div></section>';
