    html+='<section class="os-notice">'+icon('sparkles')+'<p>Personalize o atendimento para que o Orion conheça o seu negócio.</p>'+routeButton('Configurar','empresa','os-ghost os-small')+'</section>';
    html+='<section><h2 class="os-today-title">Hoje no seu negócio</h2><div class="os-stats">'+[[s.appointments,'Agendados'],[s.completed,'Atendidos'],[number(s.cancelled)+number(s.no_show),'Cancel. / faltas']].map(([v,l])=>'<div class="os-stat"><strong>'+number(v)+'</strong><small>'+l+'</small></div>').join('')+'</div><button type="button" class="os-inline-link" data-os-route="site">'+icon('external')+'Minha página de agendamento</button></section></div>';
    bodyHTML(html);
