  const agendaStates={
    confirmed:{label:'Confirmado',symbol:'check'},
    completed:{label:'Finalizado',symbol:'check'},
    no_show:{label:'Falta',symbol:'block'},
    cancelled_customer:{label:'Cancelado pelo cliente',symbol:'close'},
    cancelled_professional:{label:'Cancelado pelo profissional',symbol:'close'},
    cancelled_business:{label:'Cancelado pela empresa',symbol:'close'},
    cancelled:{label:'Cancelado',symbol:'close'},
    hold:{label:'Reserva temporária',symbol:'clock'},
    expired_hold:{label:'Reserva expirada',symbol:'clock'},
    unknown:{label:'Situação indisponível',symbol:'info'}
  };
  function appointmentState(appointment){
    const a=appointment||{};
    if(a.status==='cancelled'){
      if(a.cancellation?.event==='hold_expired')return 'expired_hold';
      const by=a.cancellation?.requested_by;
      return ['customer','professional','business'].includes(by)?'cancelled_'+by:'cancelled';
    }
    if(a.status==='hold'&&a.hold_expires_at&&Date.parse(a.hold_expires_at)<=Date.now())return 'expired_hold';
    return Object.hasOwn(agendaStates,a.status)?a.status:'unknown';
  }
  function appointmentBadge(a){
    const key=appointmentState(a),spec=agendaStates[key];
    return '<span class="os-appointment-status os-status-'+key+'">'+icon(spec.symbol)+'<span>'+esc(spec.label)+'</span></span>';
  }
  function appointmentName(a){return customerDisplayName({name:a.customer_name,display_name:a.customer_display_name,whatsapp_name:a.whatsapp_name,phone:a.customer_phone});}
  function appointmentProfessional(a){return a.professional_name||(state.data.professionals||[]).find(p=>p.id===a.professional_id)?.name||'Profissional';}
  function appointmentDuration(a){return Math.max(0,Math.round((Date.parse(a.end_at)-Date.parse(a.start_at))/60000));}
  function appointmentHistoryOnly(a){return ['cancelled','no_show'].includes(a.status)||appointmentState(a)==='expired_hold';}
