  function renderInvitations(compact=false){const team=state.data.team||{},invitations=rows(team.invitations),pending=invitations.filter(i=>['pending','claimed'].includes(i.status)),items=compact?pending:invitations;return '<section class="os-card os-team-invites"><div class="os-card-header"><div><h2>Convites</h2><p>Gere um link de acesso para sua equipe, com aprovação.</p></div>'+button('Convidar','new-invitation','os-outline os-small','plus',team.can_manage?'':'disabled')+'</div>'+(items.length?'<div class="os-invitation-list">'+items.map(i=>'<div class="os-invitation-row"><div><strong>'+esc(i.email||'Convite por link')+'</strong><small>'+esc(teamRoles[i.role]||i.role)+' · '+esc(inviteStatuses[i.status]||i.status)+(i.claimed_by_name?' · '+esc(i.claimed_by_name):'')+'</small><small>Expira em '+fmtDate(dateKey(new Date(i.expires_at)))+'</small></div><div class="os-actions">'+(team.can_manage&&i.status==='claimed'?button('Aprovar','approve-invitation','os-small','check','data-invitation="'+esc(i.id)+'"'):'')+(team.can_manage&&['pending','claimed'].includes(i.status)?button('Revogar','revoke-invitation','os-ghost os-small','close','data-invitation="'+esc(i.id)+'"'):'')+'</div></div>').join('')+'</div>':'<p class="os-help">Nenhum convite pendente.</p>')+'</section>';}
  function renderTeam(){const team=state.data.team||{},members=rows(team.members),selfEmail=String(state.bridge.user?.email||'').toLowerCase();return '<section class="os-card" style="margin-top:24px"><div class="os-card-header"><div><h2>Equipe & Permissões</h2><p>Gerencie quem pode consultar e editar o painel da empresa.</p></div>'+icon('shield')+'</div>'+(members.length?'<div class="os-table-scroll"><table class="os-table"><thead><tr><th>Pessoa</th><th>Perfil</th><th>Situação</th><th></th></tr></thead><tbody>'+members.map(member=>'<tr><td><div class="os-person"><span class="os-avatar">'+esc(initials(member.name||member.email))+'</span><div><strong>'+esc(member.name||member.email)+'</strong><small>'+esc(member.email)+'</small></div></div></td><td>'+esc(teamRoles[member.role]||member.role)+'</td><td>'+badge(member.active?'active':'inactive')+'</td><td>'+(team.can_manage&&member.role!=='owner'&&String(member.email).toLowerCase()!==selfEmail?'<button type="button" class="os-icon-button" data-os-team-member="'+esc(member.account_id)+'" aria-label="Editar acesso de '+esc(member.name||member.email)+'">'+icon('edit')+'</button>':'')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="os-finance-empty">Nenhum membro de equipe disponível para esta empresa.</p>')+'<div class="os-team-roles"><div><strong>Proprietário</strong><p>Gerencia a empresa e aprova os acessos da equipe.</p></div><div><strong>Editor</strong><p>Edita os cadastros e os dados de gestão autorizados.</p></div><div><strong>Leitor</strong><p>Consulta os dados da empresa sem fazer alterações.</p></div></div></section>'+renderInvitations();}
  function showInvitation(){if(!state.data.team?.can_manage)return;showDialog('invitation','Convidar funcionário',dialogForm('invitation',field('E-mail (opcional)','email','email','','maxlength="320" placeholder="nome@email.com"')+selectField('Perfil de acesso','role',[['editor','Editor'],['viewer','Leitor']],'editor')+'<p class="os-help">Você receberá um link para compartilhar. Depois do aceite, o proprietário aprova a entrada na equipe.</p>','Gerar link'));}
  function showInvitationResult(result){const link=safePublicURL(result.link);showDialog('invitation-result','Convite criado',link?'<p class="os-help">Copie o link agora e compartilhe com a pessoa convidada. Ele será exibido apenas nesta tela.</p><div class="os-copy-field"><input readonly value="'+esc(link)+'" aria-label="Link do convite">'+button('Copiar','copy-invitation','','copy')+'</div><p class="os-help">O convite expira em '+fmtDate(dateKey(new Date(result.expires_at)))+'. O acesso depende de aprovação depois do aceite.</p><div class="os-form-actions">'+button('Concluir','close-dialog','os-outline')+'</div>':'<p class="os-help">Este convite já havia sido criado. O link é exibido apenas uma vez. Se você perdeu o link, revogue o convite anterior e gere outro.</p><div class="os-form-actions">'+button('Fechar','close-dialog','os-outline')+button('Gerar outro convite','new-invitation','','plus')+'</div>',{link});}
  function showTeamMember(member){if(!state.data.team?.can_manage||member.role==='owner')return;showDialog('team-member','Editar acesso',dialogForm('team-member','<div class="os-person"><span class="os-avatar">'+esc(initials(member.name||member.email))+'</span><div><strong>'+esc(member.name||member.email)+'</strong><small>'+esc(member.email)+'</small></div></div>'+selectField('Perfil de acesso','role',[['editor','Editor'],['viewer','Leitor']],member.role)+checkField('Acesso ativo','active',member.active!==false),'Salvar acesso'),{record:member});}
  const paymentLabels={pix:'Pix',cash:'Dinheiro',credit_card:'Cartão de crédito',debit_card:'Cartão de débito',bank_transfer:'Transferência',other:'Outro'};
  function metric(label,value,symbol,note='',cls=''){return '<div class="os-card os-metric"><div class="os-metric-head"><span>'+esc(label)+'</span>'+icon(symbol)+'</div><strong class="'+cls+'">'+esc(value)+'</strong>'+(note?'<small>'+esc(note)+'</small>':'')+'</div>';}
  function financeTable(data,{history=false,entries=rows(data)}={}){
    let html='<div class="os-table-scroll"><table class="os-table"><thead><tr><th>Descrição</th><th>Data</th><th>Categoria</th><th>Valor</th><th>Status</th><th><span class="os-sr-only">Ações</span></th></tr></thead><tbody>'+entries.map(e=>'<tr><td><strong>'+esc(e.description)+'</strong><br><small>'+esc(paymentLabels[e.payment_method]||'')+'</small></td><td>'+fmtDate(dateKey(new Date(e.occurred_at)))+(history?'<br><small>Versão '+number(e.version)+'</small>':'')+'</td><td>'+esc(e.category||'Geral')+'</td><td class="'+(e.kind==='expense'?'os-negative':'os-positive')+'">'+(e.kind==='expense'?'− ':'+ ')+money(e.amount_cents)+'</td><td>'+badge(e.status)+'</td><td><button type="button" class="os-icon-button" data-os-finance="'+esc(e.id)+'" aria-label="Ver lançamento '+esc(e.description)+'">'+icon(writable()?'edit':'chevron')+'</button></td></tr>').join('')+'</tbody></table></div>';
    if(number(data.total)>100){const offset=state.filters.financeOffset||0;html+='<div class="os-pagination"><span>'+String(offset+1)+'–'+(offset+entries.length)+' de '+number(data.total)+'</span><div class="os-actions">'+button('Anterior','finance-page-prev','os-outline os-small','left',offset?'':'disabled')+button('Próxima','finance-page-next','os-outline os-small','chevron',offset+entries.length<number(data.total)?'':'disabled')+'</div></div>';}
    return html;
  }
  function categoryTotals(items,kind){if(!items?.length)return '<p class="os-finance-empty">Sem '+(kind==='expense'?'despesas':'receitas')+'.</p>';const maximum=Math.max(...items.map(x=>number(x.amount_cents)),1);return '<div class="os-category-list">'+items.slice(0,6).map(x=>'<div><div class="os-summary-row"><span>'+esc(x.category||'Geral')+'</span><strong>'+money(x.amount_cents)+'</strong></div><div class="os-progress"><span style="width:'+number(x.amount_cents)/maximum*100+'%;background:var(--os-'+(kind==='expense'?'danger':'success')+')"></span></div></div>').join('')+'</div>';}
  function seriesChart(series,keys=[['income_cents','Receitas','success'],['expense_cents','Despesas','danger']]){
    if(!series.length)return '<div class="os-chart-empty" aria-label="Sem movimentações no período"></div>';
    const max=Math.max(1,...series.flatMap(row=>keys.map(([key])=>number(row[key]))));
    return '<div class="os-chart-legend">'+keys.map(([,label,color])=>'<span><i style="background:var(--os-'+color+')"></i>'+esc(label)+'</span>').join('')+'</div><div class="os-series-scroll"><div class="os-series-chart" style="--os-series-count:'+series.length+'">'+series.map((row,i)=>'<div class="os-series-column">'+keys.map(([key,label,color])=>'<div class="os-series-bar" title="'+esc(fmtDate(row.date)+' · '+label+': '+money(row[key]))+'" aria-label="'+esc(fmtDate(row.date)+' · '+label+': '+money(row[key]))+'" style="height:'+Math.max(0,number(row[key])/max*100)+'%;background:var(--os-'+color+')"></div>').join('')+'<span>'+esc(String(row.date||'').slice(8,10))+'</span></div>').join('')+'</div></div>';
  }
  function renderFinance(data){
    const aggregate=state.data.financeSummary||{},s=aggregate.summary||aggregate,list=rows(data),tab=state.filters.financeTab,income=number(s.income_cents),balance=number(s.balance_cents),dre=state.data.dre?.summary||{},count=number(s.count);
    const ticket=s.average_ticket_cents;
    let html='<div class="os-finance-metrics">'+metric('Receitas',money(income),'arrowUp','','os-positive')+metric('Despesas',money(s.expense_cents),'arrowDown','','os-negative')+metric('Saldo/Lucro',money(balance),'wallet','',balance<0?'os-negative':'os-positive')+metric('Margem',(income?balance/income*100:0).toFixed(1)+'%','chart')+metric('Ticket médio',ticket!=null?money(ticket):'—','credit')+metric('Lançamentos',count,'list')+'</div>'+financeTabs();
    if(tab==='entries'){
      html+='<div class="os-finance-layout"><section class="os-card os-finance-transactions"><div class="os-card-header"><h2>Lançamentos</h2><button class="os-icon-button" type="button" data-os-action="finance-filters" aria-label="Filtrar lançamentos" title="Filtros">'+icon('settings')+'</button></div><div id="osFinanceFilters" class="os-filter-row hidden"><select id="osFinanceKind" aria-label="Tipo"><option value="">Todos os tipos</option><option value="income"'+(state.filters.financeKind==='income'?' selected':'')+'>Receitas</option><option value="expense"'+(state.filters.financeKind==='expense'?' selected':'')+'>Despesas</option></select><select id="osFinanceStatus" aria-label="Situação"><option value="">Todos os status</option>'+['paid','pending','cancelled'].map(v=>'<option value="'+v+'"'+(state.filters.financeStatus===v?' selected':'')+'>'+statusLabels[v]+'</option>').join('')+'</select></div>'+(list.length?financeTable(data):'<p class="os-finance-empty">Nenhum lançamento neste mês.</p>')+'</section><section class="os-card"><h2>Fluxo de caixa diário</h2>'+seriesChart(rows(aggregate.daily||s.daily))+'</section><section class="os-card"><h2>Top despesas por categoria</h2>'+categoryTotals(rows(s.by_category).filter(x=>number(x.expense_cents)>0).map(x=>({category:x.category,amount_cents:x.expense_cents})),'expense')+'</section><section class="os-card"><h2>Top receitas por categoria</h2>'+categoryTotals(rows(s.by_category).filter(x=>number(x.income_cents)>0).map(x=>({category:x.category,amount_cents:x.income_cents})),'income')+'</section></div>';
    }else if(tab==='dre'){
      const statement=[['Receita de serviços',dre.service_revenue_cents],['Outras receitas',dre.other_income_cents],['Receita bruta',dre.gross_revenue_cents],['(−) Comissões',-number(dre.commissions_cents)],['(−) Despesas operacionais',-number(dre.operating_expenses_cents)],['Resultado líquido',dre.net_result_cents]];
      html+='<div class="os-metrics os-dre-metrics">'+metric('Receita bruta',money(dre.gross_revenue_cents),'arrowUp','','os-positive')+metric('Comissões',money(dre.commissions_cents),'users')+metric('Despesas operacionais',money(dre.operating_expenses_cents),'arrowDown','','os-negative')+metric('Resultado líquido',money(dre.net_result_cents),'wallet')+'</div><section class="os-card os-dre-report"><div class="os-card-header"><div><h2>Demonstrativo de resultado</h2><p>'+fmtDate(state.filters.periodStart)+' a '+fmtDate(state.filters.periodEnd)+'</p></div>'+button('Imprimir / PDF','print-finance','os-outline os-small','download')+'</div><div class="os-dre-lines">'+statement.map(([label,value],i)=>'<div class="os-summary-row '+([2,5].includes(i)?'os-total':'')+'"><span>'+label+'</span><strong class="'+(number(value)<0?'os-negative':'')+'">'+money(value)+'</strong></div>').join('')+'</div><p class="os-help" style="margin-top:20px">Receitas de atendimentos concluídos e receitas extras recebidas, com desconto das comissões geradas e despesas operacionais pagas. Vales e pagamentos de comissão são registrados no caixa, sem descontar novamente a mesma comissão neste resultado.</p>'+(number(dre.legacy_rate_estimates)?'<p class="os-help" style="margin-top:8px">'+number(dre.legacy_rate_estimates)+' atendimento(s) anterior(es) ao controle de comissão usam a taxa atual do profissional como estimativa.</p>':'')+'</section>';
    }else if(tab==='commissions')html+=renderCommissionReport();
    else if(tab==='advances')html+=renderAdvances();
    else html+='<section class="os-card"><div class="os-card-header"><div><h2>Histórico de lançamentos</h2><p>Registros do período, incluindo lançamentos cancelados.</p></div></div>'+(list.length?financeTable(data,{history:true}):'<p class="os-finance-empty">Nenhum lançamento neste período.</p>')+'</section>';
    bodyHTML(html);
  }
  function renderCommissionReport(){const list=rows(state.data.commissions),can=writable();return '<section class="os-card"><div class="os-card-header"><div><h2>Comissões por profissional</h2><p>Comissões geradas por atendimentos concluídos no período.</p></div></div>'+(list.length?'<div class="os-table-scroll"><table class="os-table"><thead><tr><th>Profissional</th><th>Atendimentos</th><th>Valor vendido</th><th>Comissão</th><th>Vales no período</th><th>Saldo a pagar</th><th></th></tr></thead><tbody>'+list.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><br><small>Base '+number(p.commission_percent).toLocaleString('pt-BR')+'%</small></td><td>'+number(p.completed)+'</td><td>'+money(p.revenue_cents)+'</td><td>'+money(p.earned_cents)+'</td><td>'+money(p.advances_cents)+'</td><td>'+money(p.payable_cents)+'</td><td>'+button('Conferir quitação','settlement-preview','os-outline os-small','wallet','data-professional="'+esc(p.id)+'" '+(can?'':'disabled'))+'</td></tr>').join('')+'</tbody></table></div>':'<p class="os-finance-empty">Cadastre profissionais para acompanhar as comissões.</p>')+'<p class="os-help" style="margin-top:20px">O saldo a pagar considera todas as comissões registradas, menos os vales e pagamentos já lançados. Valores anteriores ao controle de comissão usam a taxa atual como estimativa.</p></section>';}
  const settlementLabels={open:'Em aberto',partial:'Parcial',settled:'Quitado'};
  function advanceTable(data){const list=rows(data),can=writable();return list.length?'<div class="os-table-scroll"><table class="os-table"><thead><tr><th>Profissional / descrição</th><th>Data</th><th>Valor do vale</th><th>Compensado</th><th>Em aberto</th><th>Situação</th><th></th></tr></thead><tbody>'+list.map(entry=>'<tr><td><strong>'+esc(entry.professional_name||(state.data.professionals||[]).find(p=>p.id===entry.professional_id)?.name||'Profissional')+'</strong><br><small>'+esc(entry.description)+'</small></td><td>'+fmtDate(dateKey(new Date(entry.occurred_at)))+'</td><td>'+money(entry.amount_cents)+'</td><td>'+money(entry.allocated_cents)+'</td><td>'+money(entry.pending_cents)+'</td><td>'+badge(entry.settlement_status==='settled'?'completed':'pending',settlementLabels[entry.settlement_status]||entry.settlement_status)+'</td><td><button type="button" class="os-icon-button" data-os-finance="'+esc(entry.id)+'" aria-label="Ver vale de '+esc(entry.professional_name||'profissional')+'">'+icon(can&&!number(entry.allocated_cents)?'edit':'chevron')+'</button></td></tr>').join('')+'</tbody></table></div>':'<p class="os-finance-empty">Nenhum vale neste período e situação.</p>';}
  function settlementHistory(){const data=state.data.settlements||{},items=rows(data),offset=state.filters.settlementOffset||0;return '<section class="os-card os-section-gap"><div class="os-card-header"><div><h2>Histórico de quitações</h2><p>Registros do saldo acumulado, em todos os períodos.</p></div></div>'+(items.length?'<div class="os-table-scroll"><table class="os-table"><thead><tr><th>Profissional</th><th>Registrada em</th><th>Vales compensados</th><th>Pagamento</th><th></th></tr></thead><tbody>'+items.map(item=>'<tr><td><strong>'+esc(item.professional_name)+'</strong></td><td>'+fmtDate(dateKey(new Date(item.settled_at)))+'<br><small>'+timeLabel(item.settled_at)+'</small></td><td>'+money(item.allocated_cents)+'</td><td>'+money(item.payment_cents)+'</td><td><button type="button" class="os-button os-ghost os-small" data-os-settlement="'+esc(item.id)+'">Ver registro '+icon('chevron')+'</button></td></tr>').join('')+'</tbody></table></div>':'<p class="os-finance-empty">Nenhuma quitação registrada ainda.</p>')+(number(data.total)>50?'<div class="os-pagination"><span>'+String(offset+1)+'–'+(offset+items.length)+' de '+number(data.total)+'</span><div class="os-actions">'+button('Anterior','settlement-prev','os-outline os-small','left',offset?'':'disabled')+button('Próxima','settlement-next','os-outline os-small','chevron',offset+items.length<number(data.total)?'':'disabled')+'</div></div>':'')+'</section>';}
  function renderAdvances(){
    const report=rows(state.data.commissions),sum=key=>report.reduce((n,p)=>n+number(p[key]),0),advances=state.data.financeAdvances||{},payments=state.data.financePayments||{},offset=state.filters.advanceOffset||0,paymentOffset=state.filters.paymentOffset||0;
    return '<div class="os-card-header"><div><h2>Vales & Pagamentos</h2><p>Acompanhe os adiantamentos, as compensações e os pagamentos da equipe.</p></div>'+button('Novo vale','new-advance','','plus',writable()?'':'disabled')+'</div><div class="os-metrics os-advance-metrics">'+metric('Comissão do período',money(sum('earned_cents')),'users')+metric('Vales no período',money(sum('advances_cents')),'wallet')+metric('Saldo acumulado a pagar',money(sum('payable_cents')),'credit')+'</div>'+renderCommissionReport()+'<section class="os-card os-section-gap"><div class="os-card-header"><h2>Vales</h2><select id="osAdvanceStatus" aria-label="Situação dos vales">'+[['all','Todos'],['open','Em aberto'],['partial','Parciais'],['settled','Quitados']].map(([value,label])=>'<option value="'+value+'"'+((state.filters.advanceStatus||'all')===value?' selected':'')+'>'+label+'</option>').join('')+'</select></div>'+advanceTable(advances)+(number(advances.total)>100?'<div class="os-pagination"><span>'+String(offset+1)+'–'+(offset+rows(advances).length)+' de '+number(advances.total)+'</span><div class="os-actions">'+button('Anterior','staff-finance-prev','os-outline os-small','left','data-entry-type="advance" '+(offset?'':'disabled'))+button('Próxima','staff-finance-next','os-outline os-small','chevron','data-entry-type="advance" '+(offset+rows(advances).length<number(advances.total)?'':'disabled'))+'</div></div>':'')+'<p class="os-help os-section-gap">Um vale pago representa dinheiro adiantado. A situação de quitação mostra quanto já foi compensado em uma quitação de comissões.</p></section><section class="os-card os-section-gap"><div class="os-card-header"><h2>Pagamentos registrados</h2>'+button('Registrar pagamento avulso','new-commission-payment','os-outline os-small','plus',writable()?'':'disabled')+'</div>'+(rows(payments).length?financeTable({...payments,total:rows(payments).length},{history:true}):'<p class="os-finance-empty">Nenhum pagamento registrado neste período.</p>')+(number(payments.total)>100?'<div class="os-pagination"><span>'+String(paymentOffset+1)+'–'+(paymentOffset+rows(payments).length)+' de '+number(payments.total)+'</span><div class="os-actions">'+button('Anterior','staff-finance-prev','os-outline os-small','left','data-entry-type="commission_payment" '+(paymentOffset?'':'disabled'))+button('Próxima','staff-finance-next','os-outline os-small','chevron','data-entry-type="commission_payment" '+(paymentOffset+rows(payments).length<number(payments.total)?'':'disabled'))+'</div></div>':'')+'</section>'+settlementHistory();
  }
  async function showSettlement(professionalId){
    if(!writable())return;const c=context();showDialog('settlement','Conferir quitação',loading('Consultando o saldo acumulado…'),{professionalId});const d=state.dialog;
    try{const preview=await request(mgmt('/finance/settlements/preview?'+query({professional_id:professionalId})));if(!stillAccount(c)||state.dialog!==d)return;d.preview=preview;const summary=preview.summary||{},available=number(summary.advance_allocation_cents)+number(summary.payable_cents)>0,items=rows(preview.advances).filter(item=>number(item.pending_cents)>0),content='<p class="os-help">Profissional: <strong>'+esc(preview.professional?.name)+'</strong>. Valores acumulados de todos os atendimentos concluídos registrados.</p><div class="os-summary">'+[['Comissões acumuladas',summary.earned_cents],['Pagamentos já registrados',summary.payments_cents],['Vales já compensados',summary.allocated_advances_cents],['Vales em aberto',summary.pending_advances_cents],['Vales a compensar agora',summary.advance_allocation_cents],['Pagamento a registrar',summary.payable_cents]].map(([label,value],index)=>'<div class="os-summary-row '+(index===5?'os-total':'')+'"><span>'+label+'</span><strong>'+money(value)+'</strong></div>').join('')+'</div>'+(items.length?'<details class="os-more-fields"><summary>'+icon('wallet')+'<span class="os-disclosure-label">Conferir vales desta quitação</span></summary><div class="os-disclosure-body"><div class="os-section-gap">'+items.map(item=>'<div class="os-summary-row"><span>'+esc(item.description)+'<small>Em aberto: '+money(item.pending_cents)+'</small></span><strong>'+money(item.allocation_cents)+'</strong></div>').join('')+'</div><p class="os-help os-section-gap">Os vales mais antigos são compensados primeiro. Um vale pode ficar parcialmente em aberto.</p></div></details>':'')+(available?selectField('Forma do pagamento registrado','payment_method',Object.entries(paymentLabels),'pix')+field('Data do pagamento','day','date',dateKey(),'required')+textField('Observações (opcional)','notes','','maxlength="5000"'):'<p class="os-help">Não há comissão disponível para pagar ou compensar em vales.</p>')+(number(summary.legacy_rate_estimates)?'<p class="os-help">'+number(summary.legacy_rate_estimates)+' atendimento(s) anterior(es) ao registro de comissão usam a taxa atual do profissional como estimativa.</p>':'')+'<div class="os-notice">'+icon('info')+'<p>Esta ação registra a quitação no financeiro do Orion. Ela não efetua transferência de dinheiro.</p></div>';
      $('osDialog').innerHTML='<button class="os-icon-button os-close" type="button" data-os-action="close-dialog" aria-label="Fechar">'+icon('close')+'</button><h2 id="osDialogTitle">Conferir quitação</h2>'+dialogForm('settlement',content,'Registrar quitação do saldo acumulado',button('Atualizar prévia','refresh-settlement','os-ghost os-small','refresh'));
      if(!available)$('osDialog').querySelector('button[type=submit]').disabled=true;
    }catch(error){if(stillAccount(c)&&state.dialog===d)dialogError(error);}
  }
  async function showSettlementDetail(id){const c=context();showDialog('settlement-detail','Registro de quitação',loading('Carregando registro…'));const d=state.dialog;try{const item=await request(mgmt('/finance/settlements/'+encodeURIComponent(id)));if(!stillAccount(c)||state.dialog!==d)return;const content='<div class="os-summary">'+[['Profissional',item.professional_name],['Registrada em',fmtDate(dateKey(new Date(item.settled_at)))+' às '+timeLabel(item.settled_at)],['Comissões acumuladas',money(item.earned_cents)],['Vales compensados nesta quitação',money(item.allocated_cents)],['Pagamento registrado',money(item.payment_cents)],['Identificação',item.id]].map(([label,value])=>'<div class="os-summary-row"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>').join('')+'</div>'+(rows(item.allocations).length?'<h3 class="os-section-gap">Vales compensados</h3>'+rows(item.allocations).map(row=>'<div class="os-summary-row"><span>'+esc(row.description)+'</span><strong>'+money(row.amount_cents)+'</strong></div>').join(''):'')+(item.notes?'<p class="os-help os-section-gap">'+esc(item.notes)+'</p>':'')+'<p class="os-help os-section-gap">O registro e os lançamentos vinculados preservam o histórico da quitação.</p><div class="os-form-actions">'+button('Fechar','close-dialog','os-outline')+'</div>';$('osDialog').innerHTML='<button class="os-icon-button os-close" type="button" data-os-action="close-dialog" aria-label="Fechar">'+icon('close')+'</button><h2 id="osDialogTitle">Registro de quitação</h2>'+content;}catch(error){if(stillAccount(c)&&state.dialog===d)dialogError(error);}}
