  function updateCompletionSummary(){const d=state.dialog,form=$('osDialog')?.querySelector('form');if(d?.type!=='complete-appointment'||!form)return;const coupon=d.coupons.find(c=>c.id===form.elements.coupon_id.value),a=d.record,total=number(a.total_cents);let discount=0;if(coupon){if(coupon.reward_type==='percent')discount=Math.floor((total*Math.round(number(coupon.reward_percent)*100)+5000)/10000);else if(coupon.reward_type==='fixed')discount=Math.min(total,number(coupon.reward_value_cents));else discount=Math.min(total,(a.items||[]).filter(i=>i.service_id===coupon.reward_service_id).reduce((n,i)=>n+number(i.price_snapshot_cents),0));} $('osCompleteSummary').innerHTML='<div class="os-summary-row"><span>Valor dos serviços</span><strong>'+money(total)+'</strong></div><div class="os-summary-row"><span>Desconto do cupom</span><strong>− '+money(discount)+'</strong></div><div class="os-summary-row os-total"><span>Total do atendimento</span><strong>'+money(Math.max(0,total-discount))+'</strong></div>';}
