  function renderGoogleTargets(){
    const data=state.data.google,label=$('osAgendaGoogleLabel');if(label){label.textContent=state.data.googleLoading&&!data?'Consultando conexão...':state.data.googleError?'Não foi possível consultar':googleStatusLabels[googleState(data)];label.closest('button').dataset.connection=state.data.googleError?'attention':googleState(data);}
    if($('osGoogleStatus'))$('osGoogleStatus').innerHTML=googlePanel();
    if(state.dialog?.type==='google'&&$('osGooglePanel'))$('osGooglePanel').innerHTML=googlePanel();
  }
  async function loadGoogle({handleReturn=true}={}){
    const c=context(),read=state.googleRead=(state.googleRead||0)+1;state.data.googleLoading=true;state.data.googleError=null;renderGoogleTargets();
    try{const data=await request(apiPath('/google/status'));if(!current(c)||read!==state.googleRead)return;if(!data||typeof data!=='object'||Array.isArray(data))throw Error('A situação da integração não pôde ser confirmada.');state.data.google=data;}
    catch(error){if(!current(c)||read!==state.googleRead)return;state.data.googleError=error.message||'Confira a conexão e tente novamente.';state.data.google=null;}
    finally{if(current(c)&&read===state.googleRead){state.data.googleLoading=false;renderGoogleTargets();}}
    if(!current(c)||read!==state.googleRead||!handleReturn||state.route!=='agenda')return;
    const url=new URL(location.href),returned=url.searchParams.get('google');if(!['choose','error'].includes(returned)||!tenant()||state.dialog)return;
    url.searchParams.delete('google');history.replaceState(history.state,'',url.pathname+url.search);
    if(returned==='choose'&&googleCan('can_select_calendar')&&state.data.google?.selection_pending)await showGoogleCalendars();else await showGoogle({refresh:false,notice:returned==='error'?'A autorização não foi concluída. Confira a situação da conexão e tente novamente quando estiver pronto.':''});
  }
  async function showGoogle({refresh=true,notice=''}={}){
    const appointmentId=state.dialog?.appointmentId;if(!showDialog('google','Google Agenda','<div class="os-google-dialog-intro">'+(notice?'<div class="os-notice" role="status"><p>'+esc(notice)+'</p></div>':'')+'<div id="osGooglePanel">'+googlePanel()+'</div></div>'+(appointmentId?'<div class="os-form-actions">'+button('Voltar ao agendamento','appointment-back','os-outline')+'</div>':''),{drawer:true,appointmentId}))return;
    $('osDialog').classList.add('os-google-sheet');if(refresh)await loadGoogle({handleReturn:false});
  }
  function showGoogleAction(action){
    const capability={connect:'can_connect',revoke:'can_disconnect',retry:'can_retry'}[action];if(!googleCan(capability))return;
    const titleText={connect:'Conectar Google Agenda',revoke:'Desconectar Google Agenda',retry:'Repetir sincronização'}[action],description={connect:googleDisclosure,revoke:'A autorização será removida e os novos envios serão interrompidos. Os agendamentos do Orion permanecem registrados. Os eventos já enviados não serão apagados por esta ação.',retry:'As alterações com falha serão reenviadas ao calendário escolhido. O Orion mantém o controle dos eventos para evitar duplicações.'}[action],extra=action==='connect'?'<p>Os eventos são privados e não incluem convidados. Alterações feitas diretamente no Google não voltam para a agenda do Orion.</p><p>'+(state.data.google?.calendar_change_locked?'Reconecte a mesma conta e mantenha o calendário já vinculado.':'Depois da autorização, você escolherá um calendário. Após a primeira ativação, o vínculo permanece nesse calendário.')+'</p>':'';
    showDialog('google-action',titleText,dialogForm('google-action','<div class="os-google-explainer"><p>'+esc(description)+'</p>'+extra+'</div>',action==='connect'?'Continuar com o Google':action==='revoke'?'Confirmar desconexão':'Confirmar nova tentativa'),{action,capability});
  }
  async function showGoogleCalendars(){
    if(!googleCan('can_select_calendar'))return;const c=context();if(!showDialog('google-calendar','Escolher calendário',loading('Consultando os calendários...'),{capability:'can_select_calendar'}))return;const d=state.dialog;
    try{const data=await request(apiPath('/google/calendars'));if(!current(c)||state.dialog!==d)return;if(!Array.isArray(data?.items))throw Error('Não foi possível confirmar a lista de calendários.');d.calendars=data.items;d.locked=data.calendar_change_locked===true||state.data.google?.calendar_change_locked===true;d.calendarId=data.calendar_id||state.data.google?.calendar_id;
      const available=d.calendars.filter(item=>item.selectable===true),selected=available.find(item=>item.id===d.calendarId)||(d.locked&&available.length===1?available[0]:null);$('osDialog').innerHTML='<button type="button" class="os-icon-button os-close" data-os-action="close-dialog" aria-label="Fechar">'+icon('close')+'</button><h2 id="osDialogTitle">Escolher calendário</h2>'+(available.length?dialogForm('google-calendar',selectField('Calendário do Google','calendar_id',[['','Selecione um calendário'],...available.map(item=>[item.id,item.name+(item.primary?' (principal)':'')])],d.locked?selected?.id||'':'','required')+'<div class="os-google-explainer"><p>'+esc(googleDisclosure)+'</p><p>'+(d.locked?'O calendário já vinculado será mantido. A troca para outro calendário não está disponível.':'Este calendário ficará vinculado ao Orion após a ativação. Escolha uma agenda usada pela equipe para os atendimentos.')+'</p><p>Alterações feitas diretamente no Google não voltam para o Orion.</p></div>','Ativar sincronização'):'<div class="os-agenda-error" role="status"><h3>Nenhum calendário disponível</h3><p>'+(d.locked?'O calendário já vinculado não está acessível nesta conta. Reconecte a conta que possui acesso a ele.':'Não foi encontrado um calendário com permissão de edição nesta conta.')+'</p>'+button('Voltar à conexão','agenda-google','os-outline')+'</div>');$('osDialog').querySelector('select,button:not(.os-close)')?.focus();
    }catch(error){if(current(c)&&state.dialog===d)dialogError(error);}
  }
  async function submitGoogleAction(form,d,values){
    if(!googleCan(d.capability)||state.busy)return;const action=d.type==='google-calendar'?'calendar':d.action;
    if(action==='calendar'&&!d.calendars?.some(item=>item.id===values.calendar_id&&item.selectable===true))throw Error('Escolha um calendário autorizado para esta conexão.');
    const c=context(),message=form.querySelector('.os-form-message');message.textContent='';markBusy(form,true);let done=false;
    try{const data=await request(apiPath('/google/'+action),'POST',action==='calendar'?{calendar_id:values.calendar_id}:{});if(!current(c)||state.dialog!==d)return;
      if(action==='connect'){const url=new URL(data?.authorization_url||'');if(url.protocol!=='https:'||url.hostname!=='accounts.google.com'||url.username||url.password||url.port)throw Error('O endereço de autorização do Google não foi reconhecido.');location.assign(url.href);return;}
      done=true;
    }catch(error){if(current(c)&&state.dialog===d)message.textContent=error.message||'Não foi possível concluir a alteração. Atualize a conexão antes de tentar novamente.';}
    finally{if(stillAccount(c))markBusy(form,false);else state.busy=false;}
    if(done&&current(c)&&state.dialog===d){await showGoogle({notice:action==='calendar'?'Calendário selecionado. Acompanhe a situação da sincronização abaixo.':action==='revoke'?'Conexão removida.':'Nova tentativa de sincronização solicitada.'});}
  }
  function showGoogleEmailVerification(code=false){
    const email=state.bridge.user?.email;
    if(!state.data.google?.email_confirmation_required||!email||!writable())return;
    showDialog('google-email',code?'Digite o código do e-mail':'Confirme seu e-mail',dialogForm('google-email',
      '<p>Use o e-mail da sua conta Orion: <strong>'+esc(email)+'</strong>.</p>'+
      (code?'<p>Confira sua caixa de entrada e o spam. O código vale por 10 minutos.</p>'+field('Código de confirmação','code','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6"'):
      '<p>Vamos enviar um código para confirmar que este e-mail pertence a você antes de conectar o Google Agenda.</p>'),code?'Confirmar e-mail':'Enviar código'),{email,code});
  }
  async function submitGoogleEmail(form,d,values){
    if(!state.data.google?.email_confirmation_required||d.email!==state.bridge.user?.email||state.busy)return;
    const c=context();let done=false;markBusy(form,true);
    try{
      await request(d.code?'/auth/verify':'/auth/verify/resend','POST',{email:d.email,...(d.code?{code:values.code}:{})});
      if(current(c)&&state.dialog===d)done=true;
    }catch(error){if(current(c)&&state.dialog===d)dialogError(error);}
    finally{if(stillAccount(c))markBusy(form,false);else state.busy=false;}
    if(!done||!current(c)||state.dialog!==d)return;
    if(d.code)await showGoogle({notice:'E-mail confirmado. Agora você pode conectar sua conta Google.'});
    else showGoogleEmailVerification(true);
  }
  async function loadAppointmentGoogle(d=state.dialog){
    if(d?.type!=='appointment-detail'||!d.record||!$('osAppointmentGoogle'))return;const c=context(),read=d.googleRead=(d.googleRead||0)+1;const target=$('osAppointmentGoogle');target.innerHTML=loading('Consultando sincronização...');
    try{const data=await request(apiPath('/google/appointments/'+encodeURIComponent(d.record.id)+'/status'));if(!current(c)||state.dialog!==d||read!==d.googleRead)return;const labels={pending:'Aguardando sincronização',retrying:'Nova tentativa programada',synced:'Sincronizado com o Google',failed:'Sincronização com falha',not_queued:'Sem envio registrado',outside_initial_sync:'Anterior à conexão'},configured=data.configured!==false,connected=['active','connected'].includes(data.connection_status),description=data.status==='outside_initial_sync'?'Este atendimento foi encerrado antes da conexão e não faz parte da sincronização inicial.':!configured?'A integração com Google Agenda ainda não está configurada nesta instalação.':!connected?'A conta Google não está conectada. Os dados deste agendamento permanecem no Orion.':data.status==='synced'?(d.record.status==='cancelled'?'O cancelamento foi sincronizado com o Google.':'Os dados deste agendamento foram sincronizados.'):!data.sync_enabled?'A sincronização está pausada. Os dados deste agendamento permanecem no Orion.':data.status==='not_queued'?'Este agendamento ainda não tem um envio registrado para o Google.':'A situação do Orion está atualizada, mesmo enquanto o envio ao Google está pendente.';target.innerHTML='<div class="os-appointment-google-state"><span class="os-google-mark" aria-hidden="true">G</span><div><strong>'+esc(labels[data.status]||'Situação indisponível')+'</strong><p>'+esc(description)+'</p>'+(data.last_synced_at?'<small>Último envio: '+esc(appointmentMoment(data.last_synced_at))+'</small>':'')+(data.next_attempt_at?'<small>Próxima tentativa: '+esc(appointmentMoment(data.next_attempt_at))+'</small>':'')+(data.last_error?'<p class="os-google-error">'+esc(googleErrorText(data.last_error))+'</p>':'')+'</div></div>'+button('Ver conexão','agenda-google','os-ghost os-small','link');}
    catch(error){if(current(c)&&state.dialog===d&&read===d.googleRead)target.innerHTML='<p class="os-help" role="status">Não foi possível consultar a sincronização. Os dados do agendamento continuam disponíveis.</p>'+button('Tentar novamente','appointment-google-refresh','os-ghost os-small','refresh');}
  }
  const helpCategories=[["agenda","Agenda","calendar"],["clientes","Clientes","users"],["servicos","Serviços","scissors"],["combos","Combos e adicionais","box"],["equipe","Equipe","users"],["horarios","Horários","clock"],["financeiro","Financeiro","wallet"],["comissoes","Comissões e vales","credit"],["desempenho","Desempenho","chart"],["fidelidade","Fidelização","gift"],["site","Meu site","globe"],["marketing","Marketing","sparkles"],["consultor","Consultor IA","bot"],["configuracoes","Configurações","settings"],["whatsapp","WhatsApp","phone"],["atendimento","Atendimento Orion","chat"],["catalogo","Catálogo e pedidos","box"],["conta","Conta e acesso","shield"]];
  const helpArticles=[["agendar","agenda","Como criar e confirmar um agendamento","Do cadastro do cliente à escolha do horário disponível.","agenda",["Na Agenda, escolha Novo agendamento. Busque um cliente cadastrado ou informe nome e WhatsApp. Se o cliente escolhido ainda não tiver telefone, o número informado será salvo no mesmo cadastro ao confirmar.","Escolha a data, os serviços e o profissional. O campo Horário mostra as opções que respeitam o expediente, os intervalos e os agendamentos já existentes. Se não houver opções, confira outro dia ou profissional.","Ao clicar em Agendar, o Orion registra a reserva e confirma o horário. O protocolo aparece no detalhe do agendamento. Se a confirmação demorar ou falhar, os dados ficam preservados para verificar a mesma reserva antes de tentar criar outra."]],["remarcar","agenda","Como reagendar, cancelar ou concluir um atendimento","Entenda as ações disponíveis em cada situação.","agenda",["Abra o agendamento na lista ou no calendário. Em uma reserva ou horário confirmado, você pode reagendar ou cancelar, conforme sua permissão. O Orion confere os conflitos antes de alterar o horário.","Depois do início previsto, um atendimento confirmado pode ser concluído ou marcado como ausência. Ao concluir, confira o total e escolha um cupom disponível, se houver. A comissão é registrada com a taxa usada na conclusão.","O histórico de cancelamentos e alterações permanece disponível. Um atendimento concluído não recebe um novo desconto pela edição comum do cadastro."]],["cadastro-cliente","clientes","Como cadastrar um cliente sem telefone","O nome é suficiente para iniciar o cadastro.","clientes",["Em Clientes, clique em Novo cliente. Apenas o nome é obrigatório. WhatsApp, Instagram e observações podem ser preenchidos quando você tiver essas informações.","Abra Mais dados para incluir e-mail, aniversário, bairro e cidade. Evite usar números provisórios: deixe o WhatsApp vazio até receber o contato correto.","Para fazer um agendamento, o Orion exige o WhatsApp do cliente. Ao selecionar o cadastro sem telefone na Agenda, informe o número e confirme; ele será associado ao mesmo cliente."]],["filtros-clientes","clientes","Como encontrar clientes em risco e aniversariantes","Use os filtros do diretório para acompanhar os retornos.","clientes",["O filtro Em Risco considera clientes ativos que já concluíram um atendimento, não voltaram há mais de 30, 60 ou 90 dias e não têm um agendamento futuro válido. Escolha o período nos botões do filtro.","Aniversariantes reúne os aniversários da semana atual, de domingo a sábado, usando o fuso da empresa. Um cliente sem data de nascimento não entra nesse filtro.","Inativar mantém o cadastro fora da lista de ativos. Excluir remove o cliente do diretório, preservando o histórico dos atendimentos. As duas ações exigem permissão de edição."]],["criar-servico","servicos","Como configurar preço e duração de um serviço","Prepare o catálogo e os vínculos com profissionais.","servicos",["Em Serviços, use Novo serviço, Do zero ou um modelo para iniciar o formulário. Revise nome, duração, preço e categoria antes de salvar. Um modelo apenas preenche o rascunho; nada é cadastrado automaticamente.","Selecione os profissionais que realizam o serviço. Se nenhum estiver marcado, o serviço será vinculado a todos os profissionais cadastrados. Para aceitar agendamentos, o profissional também precisa estar ativo, aceitar agenda e ter expediente.","Preparação e intervalo após o serviço reservam tempo adicional na agenda. Use os campos de cor e imagem para identificar o serviço no catálogo."]],["organizar-servicos","servicos","Como organizar ou inativar os serviços","Defina a ordem do catálogo sem apagar atendimentos passados.","servicos",["Use as setas dos cartões para mudar a posição dos serviços. A ordem é salva no catálogo da empresa.","Desative um serviço quando ele não estiver mais disponível para novos agendamentos. O histórico dos atendimentos já registrados continua preservado.","A exclusão pode ser impedida quando há vínculos que precisam ser mantidos. Nessa situação, use a opção de inativar e revise os vínculos antes de tentar novamente."]],["montar-combo","combos","Como montar um combo de serviços","Combine de dois a seis serviços com um preço próprio.","servicos",["Na seção Pacotes e combos, clique para criar um combo. Escolha de dois a seis serviços e confira a soma dos preços e da duração.","Defina o preço final diretamente ou use um percentual de desconto sobre a soma. Visibilidade e destaque controlam a apresentação do pacote.","O combo usa a duração dos serviços que o compõem. Só poderá ser agendado com profissionais que realizam todos esses serviços. Mudanças nos serviços podem alterar sua disponibilidade."]],["adicionais","combos","Como oferecer adicionais com ou sem tempo extra","Configure extras sem somar duração indevidamente.","servicos",["Abra a edição de um serviço e expanda Adicionais. Você pode escolher até cinco serviços extras do catálogo.","Para cada adicional, indique se ele deve somar tempo ao atendimento. O valor do adicional compõe o preço; a duração só aumenta quando Somar tempo está marcado.","O agendamento público usa a seleção do serviço e dos adicionais para calcular preço, duração e profissional elegível. Revise a prévia do site para conferir como essas opções aparecem."]],["profissionais","equipe","Como cadastrar profissionais e suas comissões","Separe o cadastro de atendimento do acesso ao painel.","funcionarios",["Em Funcionários, cadastre nome, especialidade, cor e taxa de comissão. O profissional pode existir na agenda sem possuir uma conta de acesso ao painel.","Ativo controla o cadastro; Aceitar agendamentos controla sua participação na disponibilidade. Vincule os serviços que ele realiza e configure os horários de trabalho.","A comissão de um atendimento é registrada quando ele é concluído. Alterar a taxa do profissional não substitui a taxa já registrada em uma conclusão com esse controle."]],["convidar-equipe","equipe","Como convidar alguém para a equipe","Crie um link de convite e aprove o acesso depois do aceite.","funcionarios",["O proprietário pode criar um convite na seção Equipe & Permissões. Escolha Editor ou Leitor e, se desejar, associe um e-mail. O sistema apresenta um link para compartilhar manualmente.","O link é exibido uma vez. Nenhum e-mail é enviado por esta ação. Se a resposta for recuperada sem o link, revogue o convite e gere outro quando precisar de um novo endereço.","Após o aceite, o convite aguarda aprovação do proprietário. Só então a pessoa passa a acessar a empresa com o papel escolhido. Proprietários não são rebaixados por esse formulário."]],["expediente","horarios","Como definir expediente e pausas","Cadastre os períodos de trabalho de cada profissional.","configuracoes",["Em Configurações, abra Horários e escolha o profissional. O resumo mostra os períodos cadastrados de segunda a domingo e a carga horária semanal.","Use Editar horários e pausas para adicionar um período de trabalho. O fim precisa ser posterior ao início. Para separar manhã e tarde, cadastre períodos diferentes ou uma pausa dentro do expediente.","Os horários usam o fuso da empresa. Alterações no expediente influenciam as novas opções disponíveis na Agenda e no agendamento público."]],["bloquear","horarios","Como bloquear horários, folgas e períodos recorrentes","Impeça novos agendamentos durante um período indisponível.","agenda",["Na Agenda, clique em Bloquear e escolha o profissional. Use Horário específico para informar data, início e fim. Use Dia inteiro / Férias para escolher o intervalo de dias.","Um horário específico pode se repetir diariamente, toda semana ou em dias da semana escolhidos, até a data final informada. A série admite no máximo 366 dias ou ocorrências.","Se um bloqueio conflitar com um agendamento existente, a série não é gravada parcialmente. Ao remover um bloqueio recorrente, escolha somente o dia, o dia e os seguintes, ou a série completa."]],["lancamentos","financeiro","Como registrar receitas e despesas","Informe valor, data, categoria e situação do lançamento.","financeiro",["Em Financeiro, selecione o mês e clique em Novo lançamento. Escolha receita ou despesa, informe a descrição, o valor e a categoria.","A situação Pago compõe o caixa realizado. Pendente identifica valores que ainda não foram recebidos ou pagos. Cancelar preserva o registro no histórico.","Confira a forma de pagamento e as observações antes de salvar. Registrar uma movimentação no Orion não realiza cobranças ou transferências externas."]],["ler-dre","financeiro","Como interpretar o DRE e o fluxo de caixa","Entenda por que resultado e movimentação de caixa podem diferir.","financeiro",["O fluxo de caixa reúne receitas e despesas pagas na data dos lançamentos. O DRE usa receitas dos atendimentos concluídos, receitas extras recebidas, comissões geradas e despesas operacionais pagas.","Vales e pagamentos de comissão movimentam o caixa, mas não descontam novamente a mesma comissão no DRE. Isso evita contabilizar a comissão duas vezes no resultado.","Atendimentos anteriores ao controle de comissão podem usar a taxa atual do profissional como estimativa. Quando isso ocorrer, o relatório identifica essa limitação."]],["registrar-vale","comissoes","Como registrar um vale para um profissional","Diferencie adiantamento pago de vale quitado.","financeiro",["Na aba Vales & Pagamentos, clique em Novo vale. Escolha o profissional, o valor, a data, a forma de pagamento e a descrição.","O vale representa um valor adiantado à pessoa. Estar pago no financeiro não significa que já foi compensado em suas comissões.","A lista de vales separa Em aberto, Parcial e Quitado. Os valores compensados são registrados durante a quitação do saldo acumulado do profissional."]],["quitar-comissao","comissoes","Como conferir e registrar uma quitação","Revise o saldo acumulado e a compensação dos vales.","financeiro",["Na tabela de comissões, use Conferir quitação. A prévia mostra comissões acumuladas, pagamentos anteriores, vales e o valor que será registrado como pagamento.","Os vales mais antigos são compensados primeiro. Se a comissão não cobrir todo o adiantamento, o vale pode permanecer parcialmente em aberto.","Confira os valores e use Registrar quitação do saldo acumulado. A ação grava o histórico financeiro e não transfere dinheiro. Se o saldo mudou desde a prévia, atualize e confira novamente."]],["periodos-desempenho","desempenho","Como comparar períodos no desempenho","Consulte atendimentos, receita e comissão por dia ou semana.","desempenho",["Em Meu desempenho, escolha Hoje, 7 dias, Mês, 30 dias, 90 dias ou um período personalizado. Os resultados usam os atendimentos concluídos dentro do período.","O gráfico pode ser agrupado por dia ou semana. Receita e comissão são somadas no agrupamento. A evolução detalhada permite conferir os valores que compõem o total.","O saldo acumulado a pagar considera todo o histórico, enquanto a comissão e os vales do período seguem o filtro. Os rótulos distinguem essas bases de cálculo."]],["metas","desempenho","Como acompanhar metas da equipe","Defina objetivos com período e unidade claros.","desempenho",["Na seção Metas da equipe, crie uma meta de atendimentos ou faturamento para um profissional. Informe as datas de início e fim e o objetivo.","O progresso é calculado a partir dos registros reais da agenda. O valor realizado aparece ao lado do objetivo definido.","Uma meta pode ser desativada sem apagar o histórico. A meta de faturamento usa valores em reais; a meta de atendimentos usa uma quantidade inteira."]],["programa-pontos","fidelidade","Como configurar o programa de fidelidade","Combine pontos por valor gasto e por atendimento.","fidelizacao",["Em Fidelização, abra Configurar. Defina os pontos por valor gasto e por atendimento, a meta de pontos, o tipo de recompensa e a validade do cupom.","Os ganhos por valor e por atendimento podem se somar. A conclusão de um atendimento em um programa ativo acumula pontos e pode emitir até um cupom. Os pontos excedentes permanecem no saldo.","Apenas um programa fica ativo por vez. Cupons percentuais, de valor fixo e de serviço grátis possuem configurações próprias. Confira o benefício antes de ativar o programa."]],["usar-cupom","fidelidade","Como emitir e usar um cupom","Acompanhe o saldo, a validade e o atendimento de resgate.","fidelizacao",["No Ranking, acompanhe os pontos de cada cliente. Perto do prêmio destaca quem atingiu ao menos 70% da meta do programa.","Quando houver saldo suficiente, um cupom pode ser emitido manualmente. A emissão consome os pontos necessários e preserva o excedente. A aba Cupons mostra código, validade e situação.","Para usar um cupom, abra o atendimento confirmado e clique em Concluir atendimento. Escolha um benefício disponível para o cliente e confira o desconto. O uso só é registrado quando a conclusão é salva."]],["publicar-site","site","Como revisar e publicar sua página","Saiba a diferença entre salvar o rascunho e publicar.","site",["Em Meu Site, abra Configurações. Preencha nome, contato, apresentação, endereço, imagens e links. Salvar atualiza o rascunho da página.","Use Visualizar prévia para revisar o conteúdo salvo. A prévia não registra visitas nas métricas. Quando estiver pronto, o proprietário usa Publicar página ou Publicar alterações.","Alterar o endereço do site no rascunho não troca imediatamente a página pública. O novo endereço passa a valer após a publicação. Retirar do ar preserva os agendamentos e as configurações."]],["metricas-site","site","O que as métricas do site contabilizam","Acompanhe visitas, clientes e agendamentos públicos.","site",["O Painel de Meu Site mostra acessos, clientes distintos que agendaram, agendamentos confirmados pelo site e taxa de agendamento nos últimos 30 dias.","A taxa divide a quantidade de agendamentos públicos pelos acessos registrados. O gráfico apresenta as contagens de cada dia no fuso da empresa.","As prévias e os agendamentos feitos pela equipe no painel não entram nesses indicadores. Os dados descrevem o uso registrado da página, sem estimar visitantes externos."]],["gerar-campanha","marketing","Como criar uma campanha com IA","Gere os textos, revise a oferta e salve um rascunho.","marketing",["Abra Marketing IA e selecione Campanhas. Descreva o que deseja promover e escolha o tom da mensagem. A IA só é consultada quando você clicar em Gerar campanha.","O resultado pode incluir nome, oferta e textos para WhatsApp, Instagram, Stories e notificação. Confira preços, condições e promessas antes de usar o conteúdo.","Você pode copiar os textos ou salvar um rascunho para revisão. Gerar ou salvar a campanha não envia mensagens aos clientes. A disponibilidade de geração depende da configuração e do limite diário da empresa."]],["automacoes-fila","marketing","Como diferenciar automações e fila de respostas","Planeje rotinas e acompanhe as respostas do atendimento.","marketing",["Na aba Automações, prepare textos e preferências de confirmações, lembretes, recuperação, aniversários e fidelidade. As configurações ficam em rascunho; marcar ou salvar uma rotina não inicia envios.","A Fila de envios mostra as respostas reais do atendimento WhatsApp via Meta, com situação, tentativas e data. Ela não representa campanhas disparadas pelo Marketing.","Use os filtros Pendentes, Enviadas, Com falha e Todas para consultar a fila. Quando houver falha, confira a operação do canal de atendimento."]],["consultar-ia","consultor","Como conversar com o Consultor IA","Faça perguntas a partir dos dados da empresa.","consultor",["No Consultor IA, escreva uma pergunta sobre seus resultados ou escolha uma sugestão. A pergunta só é enviada ao provedor quando você usa o botão de envio.","As respostas usam informações agregadas da empresa, como atendimentos, faturamento, catálogo e programa de fidelidade. A seção Dados usados nesta resposta apresenta o período e as bases consultadas.","O consultor pode sugerir ações e atalhos. Nenhuma alteração é executada automaticamente. Confira as sugestões e abra a área correspondente quando quiser agir."]],["limite-ia","consultor","Como funciona o limite diário de gerações","Consulte a disponibilidade sem consumir uma geração.","configuracoes",["Em Configurações, abra Uso de IA para ver o limite diário, o total utilizado e o saldo disponível. O limite é compartilhado pelas ferramentas de IA da empresa.","Abrir uma tela, ler o histórico ou consultar a disponibilidade não chama o provedor. A geração começa após uma ação explícita, como Gerar campanha ou enviar uma pergunta.","A cota é renovada à meia-noite UTC. Se a IA estiver desativada, sem configuração ou sem saldo diário, o painel explica a situação e não inicia uma geração."]],["dados-negocio","configuracoes","Como editar os dados operacionais e fiscais","Mantenha os dados internos separados da página pública.","configuracoes",["Em Configurações, abra Negócio. O proprietário pode editar telefone administrativo, meta mensal, documento, nome fantasia e razão social.","Esses dados são internos e não substituem as informações públicas de Meu Site. Revise cada área conforme o uso pretendido.","Os convites para avaliação e o relatório semanal são preferências em rascunho. O painel informa quando a execução automática ainda não está habilitada."]],["aparencia","configuracoes","Como escolher entre claro, escuro e sistema","Ajuste a aparência para o dispositivo que você usa.","configuracoes",["Use o ícone de aparência no cabeçalho ou abra Configurações e Aparência. Escolha Claro, Escuro ou Sistema.","Sistema acompanha a preferência de aparência do dispositivo. A escolha fica disponível neste navegador e não altera os dados da empresa.","O menu se adapta à largura da tela. No celular, use o botão do cabeçalho para abrir a navegação; no computador, o controle de recolher reduz a barra lateral."]],["canal-whatsapp","whatsapp","Como consultar a conexão do WhatsApp","A operação do canal depende do acesso autorizado.","dispositivo",["A conexão do WhatsApp é operada por contas de administração autorizadas do Orion. Quando esse acesso estiver disponível, o menu Conectar WhatsApp abre o fluxo existente de dispositivo.","Siga o estado apresentado pelo assistente de conexão. Um código ou QR Code pode expirar; consulte a tela para verificar a etapa atual antes de tentar novamente.","Os acessos comuns da empresa não recebem automaticamente permissão para operar dispositivos. O cadastro de profissionais da agenda é independente da administração do canal."]],["respostas-whatsapp","whatsapp","Onde acompanhar mensagens pendentes ou com falha","Consulte a fila real de respostas Meta.","marketing",["Em Marketing IA, abra Fila de envios. A lista reúne respostas do canal Meta que já entraram no processamento do atendimento.","Cada registro mostra o final do telefone, a situação, o número de tentativas e, quando aplicável, a próxima tentativa. O painel preserva o número completo do destinatário nessa listagem.","O filtro Com falha identifica respostas que exigem atenção da operação. Salvar um rascunho de campanha não adiciona uma mensagem a essa fila."]],["configurar-atendimento","atendimento","Como preparar o atendimento do Orion","Revise o conhecimento do negócio antes de publicar uma versão.","empresa",["Abra Configurar atendimento no menu Atendimento Orion. Essa área mantém as informações e regras que o assistente usa para responder sobre a empresa.","Revise o conteúdo, os serviços e as orientações aplicáveis ao negócio. Use o simulador para conferir como as respostas se comportam com perguntas reais de teste.","As configurações de atendimento seguem seu próprio fluxo de revisão e publicação. Salvar a apresentação de Meu Site não publica automaticamente uma versão do atendimento."]],["testar-audio","atendimento","Como testar respostas de texto e áudio","Use o simulador para conferir o atendimento configurado.","ai",["Abra Testar atendimento para usar o simulador existente do Orion. Escolha os controles de texto e áudio disponíveis para sua configuração.","Faça perguntas que representem o uso do seu negócio: serviços, horários, condições e dúvidas frequentes. Revise se a resposta está coerente com as informações cadastradas.","A disponibilidade de áudio e do provedor depende da configuração do servidor. Uma mensagem de indisponibilidade indica que é necessário revisar a integração antes de usar o recurso."]],["catalogo-pedidos","catalogo","Como acessar o catálogo comercial e os pedidos","Encontre o módulo de comércio já existente no Orion.","catalogo",["O menu Catálogo e pedidos mantém o módulo comercial do Orion. Seus produtos e pedidos são separados dos serviços de atendimento cadastrados na Agenda.","Consulte a área correspondente para revisar catálogo e situação dos pedidos. As operações dependem da ativação do módulo e das permissões da empresa.","Se o catálogo estiver desativado pelo servidor, o painel informa a indisponibilidade. Cadastrar um serviço na Agenda não cria automaticamente um produto comercial."]],["cadastros-avancados","configuracoes","Onde administrar telefones autorizados e folgas","Encontre os controles específicos do atendimento Orion.","cadastros",["Em Configurações, abra Administração e use Administração do atendimento. Essa área reúne os telefones autorizados e os períodos de folga dos profissionais.","A consulta e a edição respeitam o acesso à empresa. Somente o proprietário e a administração podem alterar os telefones autorizados da empresa vinculada à conta.","Para serviços, profissionais, horários e bloqueios, use as abas correspondentes no menu de gestão. Os links antigos de cadastros continuam abrindo a área administrativa."]],["empresa-da-conta","conta","Como acessar a empresa da minha conta","Seu negócio fica vinculado ao seu acesso.","dashboard",["Cada conta acessa uma única empresa. O nome do negócio aparece no topo do menu, sem precisar selecionar um estabelecimento.","A agenda, os clientes, o financeiro e as configurações pertencem à empresa vinculada à conta autenticada.","Se o painel informar um problema no vínculo, verifique novamente ou entre com a conta da empresa. Dados de outro negócio não são escolhidos automaticamente."]],["permissoes","conta","O que cada papel pode fazer","Entenda proprietário, editor e leitor.","funcionarios",["O proprietário administra o acesso da equipe e a publicação da página pública. O Editor executa as operações de gestão permitidas pelo módulo. O Leitor consulta os dados, com controles de gravação desabilitados.","Algumas preferências, como dados fiscais e operacionais, ficam restritas ao proprietário. Operações de infraestrutura do Orion podem exigir acesso de administração.","Os convites para Editor ou Leitor precisam ser aceitos e aprovados. A leitura de notificações é individual, por isso um leitor pode marcar seus próprios avisos como lidos sem alterar os agendamentos."]]];
  const releaseNotes=[["feature","Gestão em um só painel","Agenda, clientes, serviços e equipe passam a usar uma navegação comum para celular, tablet e computador.",["A barra lateral reúne as áreas de gestão e os módulos já existentes de atendimento Orion.","O tema pode ser claro, escuro ou acompanhar o dispositivo."],"dashboard"],["feature","Página pública com revisão antes de publicar","A apresentação do negócio pode ser salva, conferida em prévia e publicada pelo proprietário.",["As métricas separam acessos e confirmações pelo site público.","As prévias ficam fora da contagem de visitas e não criam reservas públicas."],"site"],["feature","Comissões, vales e quitações","A gestão financeira ganha uma conferência do saldo acumulado de cada profissional.",["A quitação registra a compensação de vales por ordem de antiguidade.","Os lançamentos vinculados preservam o histórico da operação, sem realizar transferência externa."],"financeiro"],["feature","Pontos e cupons de fidelidade","O programa usa os atendimentos concluídos para acumular pontos e emitir benefícios.",["Os pontos por valor e por atendimento podem ser combinados.","Cada conclusão gera no máximo um cupom automático e mantém os pontos excedentes."],"fidelizacao"],["improvement","Mais formas de organizar a agenda","Calendário, lista e visão por profissional compartilham os dados reais da agenda.",["O modo tablet oferece uma visualização dedicada.","Bloqueios recorrentes podem ser removidos por ocorrência, a partir de uma data ou por série."],"agenda"],["improvement","Campanhas revisáveis e fontes da IA","As ferramentas de IA geram conteúdo a partir de uma ação explícita e mostram a base consultada.",["Campanhas podem ser copiadas ou salvas como rascunho.","As rotinas de automação preparadas no painel continuam identificadas como rascunhos."],"marketing"],["fix","Confirmação de reserva com dados preservados","Uma falha de confirmação mantém a mesma reserva disponível para conferência.",["O formulário evita confirmar uma reserva anterior com dados que tenham sido alterados depois da tentativa.","O protocolo permite conferir o estado na Agenda antes de criar outro agendamento."],"agenda"],["fix","Dados da sua conta durante a navegação","A saída da conta descarta consultas e buscas do contexto anterior.",["Respostas atrasadas não substituem os dados da conta autenticada.","As ações continuam vinculadas ao acesso autorizado da conta."],"dashboard"]];
  const normalizedSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
  function helpCategory(id){return helpCategories.find(item=>item[0]===id)||['','Orientação','book'];}
  function helpCard(article,featured=false){return '<button type="button" class="os-help-card '+(featured?'os-help-featured':'')+'" data-os-help-article="'+article[0]+'"><span class="os-badge os-neutral">'+helpCategory(article[1])[1]+'</span><h2>'+esc(article[2])+'</h2><p>'+esc(article[3])+'</p><span class="os-help-card-footer"><span>'+icon('clock')+'1 min de leitura</span><span>Ler '+icon('arrow')+'</span></span></button>';}
  function renderHelp(){
    const article=helpArticles.find(item=>item[0]===state.filters.helpArticle);if(article){renderHelpArticle(article);return;}
    bodyHTML('<header class="os-help-hero"><span class="os-badge os-help-count">'+icon('book')+helpArticles.length+' artigos disponíveis</span><h1>Base de conhecimento</h1><p>Guias práticos para configurar seu negócio e usar o Orion: agenda, equipe, clientes, financeiro e atendimento.</p><div class="os-search">'+icon('search')+'<input id="osHelpSearch" type="search" placeholder="O que você quer aprender?" value="'+esc(state.filters.helpQuery)+'" aria-label="Buscar artigos"></div></header><div class="os-help-categories" role="group" aria-label="Categorias de artigos">'+[['all','Todos','book'],...helpCategories].map(([id,label,symbol])=>'<button type="button" class="os-pill-tab" data-os-help-category="'+id+'" aria-pressed="'+(state.filters.helpCategory===id)+'">'+icon(symbol)+label+'</button>').join('')+'</div><div id="osHelpResults"></div>');renderHelpResults();
  }
  function renderHelpResults(){const query=normalizedSearch(state.filters.helpQuery),category=state.filters.helpCategory,list=helpArticles.filter(article=>(category==='all'||article[1]===category)&&(!query||normalizedSearch(article[2]+' '+article[3]+' '+article[5].join(' ')).includes(query))),featured=!query&&category==='all'?[helpArticles.find(article=>article[0]==='bloquear'),helpArticles[0]]:[];const target=$('osHelpResults');if(!target)return;target.innerHTML='<div class="os-help-results-heading"><p>'+list.length+' artigo'+(list.length===1?' encontrado':'s encontrados')+'</p></div>'+(featured.length?'<section class="os-help-featured-grid" aria-label="Artigos em destaque">'+featured.map(article=>helpCard(article,true)).join('')+'</section>':'')+(list.length?'<section class="os-help-grid" aria-label="Artigos">'+list.filter(article=>!featured.some(item=>item[0]===article[0])).map(article=>helpCard(article)).join('')+'</section>':'<section class="os-card">'+empty('search','Nenhum artigo encontrado','Tente buscar por outro termo ou escolha outra categoria.')+'</section>');}
  function renderHelpArticle(article){const category=helpCategory(article[1]),related=[...helpArticles.filter(item=>item[0]!==article[0]&&item[1]===article[1]),...helpArticles.filter(item=>item[0]!==article[0]&&item[1]!==article[1])].slice(0,3);bodyHTML('<article class="os-help-article">'+button('Voltar para a base','help-back','os-ghost','left')+'<header><span class="os-badge os-neutral">'+category[1]+'</span><h1>'+esc(article[2])+'</h1><p class="os-help-article-meta">'+icon('clock')+'1 min de leitura <span>Guia da gestão Orion</span></p></header><div class="os-help-prose">'+article[5].map(paragraph=>'<p>'+esc(paragraph)+'</p>').join('')+'</div><div class="os-form-actions">'+routeButton('Abrir '+routeNames[article[4]],article[4],'os-outline',category[2])+'</div><section class="os-help-related"><h2>Continue lendo</h2><div>'+related.map(item=>'<button type="button" data-os-help-article="'+item[0]+'"><strong>'+esc(item[2])+'</strong><span>Ler '+icon('arrow')+'</span></button>').join('')+'</div></section><section class="os-card os-help-article-footer"><h3>Precisa consultar seus dados?</h3><p>Abra a área correspondente do painel para conferir os registros da sua empresa.</p>'+routeButton('Voltar ao painel','dashboard','os-outline os-small','dashboard')+'</section></article>');}
  function openHelpArticle(id){if(!helpArticles.some(article=>article[0]===id))return;state.filters.helpArticle=id;renderHelp();window.scrollTo({top:0,behavior:'instant'});}
